using System;
using Fanex.Common;
using Fanex.Data.Configuration;
using Fanex.NAPReport.RngCasino.Business.Business;
using Fanex.NAPReport.RngCasino.Business.Business.Exports;
using Fanex.NAPReport.RngCasino.Business.Business.Exports.ExcelExport;
using Fanex.NAPReport.RngCasino.Business.Configuration;
using Fanex.NAPReport.RngCasino.Business.Helper.Implement;
using Fanex.Service.Core.Configuration;
using Fanex.MailDelivery.Client.Handlers;

namespace Fanex.NAPReport.RngCasino.Testing
{
	class Program
	{
		static void Main(string[] args)
		{
			try
			{
				DbSettingProviderManager.Current.Start();

				var configurationParser = new ConfigurationParser(AppDomain.CurrentDomain.BaseDirectory +
																@"\Configuration\RngCasino.Settings.xml");

				configurationParser.Parse<RngCasinoSettings>();

				var excelService = new RngCasinoExcelService();
				var exportSettings = new ExportSettings();

				CustomerWinLossService customerService = new CustomerWinLossService(excelService, exportSettings);

				var winloss = RngCasinoSettings.WinLoss;

				var dateTimeFormat = "{0:yyyy-MM-dd HH:mm}";
				var toDate = string.Format(dateTimeFormat, DateTime.Now);
				var fromDate = string.Format(dateTimeFormat, DateTime.Now.AddMinutes(-RngCasinoSettings.TimeInterval - 10000));

				var subject = string.Format(RngCasinoSettings.Subject, RngCasinoSettings.BaseCurrency,
					NumberExtension.WinLossFormat(winloss, 0), fromDate, toDate);

				MailClientHandler.Start();
				customerService.SendMail(Converter.ToDateTime(fromDate), Converter.ToDateTime(toDate), winloss, subject, RngCasinoSettings.Title);
				MailClientHandler.Stop();
			}
			catch (Exception ex)
			{
				Console.WriteLine(ex.Message);
				Console.ReadLine();
			}
		}
	}
}
